    const nameDisplayTh = cycle === 1 ? seed.nameTh : `${seed.nameTh} (ทำเนียบสยาม #${cycle})`;
    const nameDisplayEn = cycle === 1 ? seed.nameEn : `${seed.nameEn} (Siam Archive #${cycle})`;

